#!/usr/bin/env node
// campaign-bundle.mjs — single-file Workflow bundler for the #749 campaign engine.
//
// Same contract as bundle.mjs (the per-wave bundler): a Dynamic Workflow MUST be ONE self-contained
// file with `export const meta` as the literal first statement — cross-file `import`s do NOT run as
// a Workflow. The deterministic core (campaign-loop.js) lives in a separate module SO IT CAN BE
// UNIT-TESTED (a Workflow file uses top-level return/await, illegal in a plain ESM module). This
// script inlines core → workflow into campaign-workflow.bundled.js. A regression test
// (tests/regression/test_campaign_bundle_in_sync.sh) asserts the committed bundle matches a fresh
// regeneration so the two never drift.
//
// USAGE:
//   node skills/nextwave/campaign-bundle.mjs            # regenerate the committed bundle
//   node skills/nextwave/campaign-bundle.mjs --check    # exit 1 if the committed bundle is stale

import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const DIR = dirname(fileURLToPath(import.meta.url))
const MODULES = ['campaign-loop.js'] // dependency order: the workflow imports the pure core
const MAIN = 'campaign-workflow.js'
const OUT = 'campaign-workflow.bundled.js'

function stripImports(src) {
  return src.replace(/^import\s+[\s\S]*?from\s*['"][^'"]+['"];?[ \t]*$/gm, '')
}
function stripExports(src) {
  return src.replace(/^export\s+(?=(async\s+function|function|const|let|var|class)\b)/gm, '')
}
function extractMeta(src) {
  const m = src.match(/export\s+const\s+meta\s*=\s*\{/)
  if (!m) throw new Error(`campaign-bundle: \`export const meta = {\` not found in ${MAIN}`)
  const start = m.index
  const braceOpen = src.indexOf('{', start)
  let depth = 0
  let i = braceOpen
  for (; i < src.length; i++) {
    if (src[i] === '{') depth++
    else if (src[i] === '}') {
      depth--
      if (depth === 0) {
        i++
        break
      }
    }
  }
  if (depth !== 0) throw new Error(`campaign-bundle: unbalanced braces in \`meta\` block of ${MAIN}`)
  if (src[i] === ';') i++
  return { metaBlock: src.slice(start, i), rest: src.slice(0, start) + src.slice(i) }
}

export function buildBundle() {
  const read = (f) => readFileSync(join(DIR, f), 'utf8')
  const main = read(MAIN)
  const { metaBlock, rest } = extractMeta(main)
  const modulesInlined = MODULES.map((f) => {
    const body = stripExports(stripImports(read(f))).trim()
    return `// ════════════ inlined: ${f} ════════════\n${body}\n`
  }).join('\n')
  const mainInlined = stripExports(stripImports(rest)).trim()
  return [
    `// campaign-workflow.bundled.js — GENERATED by skills/nextwave/campaign-bundle.mjs. DO NOT EDIT.`,
    `// Source of truth (edit these, then re-run the bundler): ${MAIN} + ${MODULES.join(' + ')}.`,
    `// Single-file Workflow artifact: \`export const meta\` first, no imports.`,
    `// Regenerate: node skills/nextwave/campaign-bundle.mjs   ·   Drift guard: tests/regression/test_campaign_bundle_in_sync.sh`,
    ``,
    metaBlock,
    ``,
    modulesInlined,
    `// ════════════ workflow body: ${MAIN} ════════════`,
    mainInlined,
    ``,
  ].join('\n')
}

const isCheck = process.argv.includes('--check')
const outPath = join(DIR, OUT)
const next = buildBundle()
if (isCheck) {
  let current = ''
  try {
    current = readFileSync(outPath, 'utf8')
  } catch {
    /* missing → stale */
  }
  if (current !== next) {
    console.error(`[campaign-bundle --check] ${OUT} is STALE — run: node skills/nextwave/campaign-bundle.mjs`)
    process.exit(1)
  }
  console.log(`[campaign-bundle --check] ${OUT} is up to date`)
} else {
  writeFileSync(outPath, next)
  console.log(`[campaign-bundle] wrote ${OUT} (${next.length} bytes)`)
}
